-- ============================================================================
-- 208: Seed the competency catalogue from the MATATAG learning competencies
-- Part 19 of 22: Grade 12
-- ============================================================================
-- Source: Learning_Competencies_Split.xlsx (Kindergarten to Grade 12, one row
-- per competency). Columns taken: Grade Level, Subject, Term, Week,
-- Domain / Subdomain / Content, Learning Competency. Requires 207.
--
--   6718 entries across 110 learning areas (10 exact duplicate rows in
--   the sheet dropped).
--
-- Mapping
--   Subject      -> sms_learning_areas.name, created if missing (matched on
--                   lower(btrim(name)), the unique index from 195). Spacing
--                   before a colon and en/em dashes are normalised so
--                   "EPP : AFA" and "EPP: AFA" are one area.
--   Grade Level  -> grade_level (Kindergarten = 0).
--   Term         -> term 1 / 2 / 3; a blank term is NULL.
--   Week, Domain -> verbatim, whitespace collapsed.
--   Competency   -> competency_text, whitespace collapsed (195's trigger
--                   would do the same).
--
-- LC codes: the sheet carries none, and lc_code is NOT NULL and the import
-- key (195). Each entry gets a sequential code per (learning area, grade) in
-- sheet order: K-001, G5-001, G5-002 ... so the catalogue lists in curriculum
-- order. Replace a code with the official one later through the catalogue's
-- typo edit; a TOS already saved keeps the code it copied.
--
-- Split into parts because the Supabase SQL editor refuses a query this
-- large. Each part is self-contained and may run in any order; run them all.
-- Idempotent: ON CONFLICT DO NOTHING on both tables, so re-running a part
-- inserts nothing and never overwrites an entry edited since. No UPDATE, no DELETE.
-- Ends with a verification SELECT (the SQL editor shows only the last result).
-- ============================================================================

INSERT INTO procurements.sms_learning_areas (name)
VALUES
  ('Art Criticism and Creative Markets'),
  ('Citizenship and Civic Engagement'),
  ('Contemporary Literature 1'),
  ('Contemporary Literature 2'),
  ('Creative Composition 1'),
  ('Creative Composition 2'),
  ('Creative Industries - Applied and Traditional Arts'),
  ('Creative Industries - Dance'),
  ('Creative Industries - Literary Arts'),
  ('Creative Industries - Media Arts'),
  ('Creative Industries - Music'),
  ('Creative Industries - Theater Arts'),
  ('Creative Industries - Visual Arts'),
  ('Creative Production and Presentation'),
  ('Filipino 1 (Wika at Komunikasyon sa Akademikong Filipino)'),
  ('Filipino 2 (Filipino sa Isports)'),
  ('Filipino 2 (Filipino sa Larang Teknikal-Propesyonal)'),
  ('Filipino 2 (Filipino sa Sining at Disenyo)')
ON CONFLICT ((lower(btrim(name)))) DO NOTHING;

/* Grade 12: 216 */
INSERT INTO procurements.sms_competency_catalogue
  (learning_area_id, grade_level, lc_code, competency_text, term, week, domain)
SELECT a.id, v.grade_level::int, v.lc_code::text, v.competency_text::text, v.term::smallint, v.week::text, v.domain::text
FROM (VALUES
  ('Art Criticism and Creative Markets', 12, 'G12-001', 'analyze the role of formal analysis and aesthetic theories in developing critical reviews of creative works in visual, literary, media, applied, and traditional arts;', NULL, NULL, 'I. Art Criticism A. Definition and Importance of Art Criticism 1. Importance of Art Criticism for Artists, Audiences, and the Creative Industries 2. Who Can Be an Art Critic B. Formal Analysis 1. Description 2. Analysis 3. Interpretation 4. Evaluation C. Aesthetic Theories and Judgment 1. Imitationalism 2. Formalism 3. Emotionalism D. Components of Effective Art 1. Composition 2. Technical Skill 3. Expression E. Critiquing Art Across Domains Toward Organic Unity 1. Subject, Themes, and Inspirations 2. Form and Structure 3. Content and Composition 4. Aesthetics, Styles, Conventions, and Experimentations'),
  ('Art Criticism and Creative Markets', 12, 'G12-002', 'examine how art markets, platforms, and entrepreneurial pathways influence the creation and distribution of art in socio- economic and cultural contexts; and', NULL, NULL, 'II. Various Art Markets A. Brief Overview of the Creative Industries B. Venues, Platforms, and Channels 1. Collectors and Patrons'),
  ('Art Criticism and Creative Markets', 12, 'G12-003', 'organize a small-scale art fair that effectively communicates its message or purpose to a defined audience.', NULL, NULL, 'III. Organizing a Small-Scale Art Fair A. Concept and Curation 1. Identifying a Theme, Message, or Purpose 2. Curating Artworks, Literary Texts, and Performances B. Audience and Market Considerations 1. Identifying Target Audience 2. Considering Audience Needs and Market Context C. Exhibition Design and Production 1. Overall Programming of the Art Fair 2. Layout and Presentation of Artworks and Texts 3. Installation and Setup 4. Planning Performance Spaces D. Promotion and Communication 1. Promoting the Art Fair'),
  ('Citizenship and Civic Engagement', 12, 'G12-001', 'Examine the meaning and importance of active and empowered citizenship', NULL, NULL, 'Citizenship • What is citizenship? • Who is the Filipino citizen? • What are suffrage and the roles and responsibilities of the Filipino voter? Elections and Political Parties • The nature of elections and political parties in the context of the Philippines The Rights of Filipino Citizens • The Bill of Rights • Social Justice and Human Rights As outlined in the 1987 Philippine Constitution, Filipino citizens have the following key responsibilities: 1. Defend the State (Article II, Section 4) – Serve and protect the country when required. 2. Obey the Law – Follow all laws, rules, and regulations. 3. Pay Taxes (Article VI, Section 28) – Contribute to public funds through taxes. 4. Participate in Democratic Processes (Article V) – Exercise the right to vote wisely and engage in civic activities. 5. Promote the Common Good (Article II, Section 1 & 27) – Support efforts that advance national welfare.'),
  ('Citizenship and Civic Engagement', 12, 'G12-002', 'Analyze the electoral process, implications of different electoral systems on politics and governance, and the role of political parties in a democracy', NULL, NULL, 'Citizenship • What is citizenship? • Who is the Filipino citizen? • What are suffrage and the roles and responsibilities of the Filipino voter? Elections and Political Parties • The nature of elections and political parties in the context of the Philippines The Rights of Filipino Citizens • The Bill of Rights • Social Justice and Human Rights As outlined in the 1987 Philippine Constitution, Filipino citizens have the following key responsibilities: 1. Defend the State (Article II, Section 4) – Serve and protect the country when required. 2. Obey the Law – Follow all laws, rules, and regulations. 3. Pay Taxes (Article VI, Section 28) – Contribute to public funds through taxes. 4. Participate in Democratic Processes (Article V) – Exercise the right to vote wisely and engage in civic activities. 5. Promote the Common Good (Article II, Section 1 & 27) – Support efforts that advance national welfare.'),
  ('Citizenship and Civic Engagement', 12, 'G12-003', 'Analyze the relationship between citizens'' rights and responsibilities in fostering active citizenship and good governance', NULL, NULL, 'Citizenship • What is citizenship? • Who is the Filipino citizen? • What are suffrage and the roles and responsibilities of the Filipino voter? Elections and Political Parties • The nature of elections and political parties in the context of the Philippines The Rights of Filipino Citizens • The Bill of Rights • Social Justice and Human Rights As outlined in the 1987 Philippine Constitution, Filipino citizens have the following key responsibilities: 1. Defend the State (Article II, Section 4) – Serve and protect the country when required. 2. Obey the Law – Follow all laws, rules, and regulations. 3. Pay Taxes (Article VI, Section 28) – Contribute to public funds through taxes. 4. Participate in Democratic Processes (Article V) – Exercise the right to vote wisely and engage in civic activities. 5. Promote the Common Good (Article II, Section 1 & 27) – Support efforts that advance national welfare.'),
  ('Citizenship and Civic Engagement', 12, 'G12-004', 'Assess the roles and contributions of civil society organizations and social movements to Philippine democracy', NULL, NULL, '6. Respect the Rights of Others (Article III) – Uphold the dignity and freedoms of fellow citizens. 7. Protect the Environment (Article II, Section 16) Contribute to Environmental Preservation. 8. Practice Honesty and Integrity (Article XI) – Uphold ethical behavior in personal and public life. 9. Render Civic Service – Participate in community service and volunteer activities. Civil Society Organizations, Social Movements and Non-movements • Political participation outside formal institutions Community Engagement and Development • Definition and Forms of Community Engagement: o Volunteerism o Community organizing o Participatory governance o Advocacy and civic movements o Public consultations and forums • Principles of Effective Community Engagement: o Inclusivity and participation o Empowerment of local communities o Collaboration and partnership building • Role of Community Engagement in Development: o Enhancing public services o Promoting sustainable development o Strengthening civic participation Community Action'),
  ('Citizenship and Civic Engagement', 12, 'G12-005', 'Examine forms of community engagement that contribute to community development through solidarity', NULL, NULL, '6. Respect the Rights of Others (Article III) – Uphold the dignity and freedoms of fellow citizens. 7. Protect the Environment (Article II, Section 16) Contribute to Environmental Preservation. 8. Practice Honesty and Integrity (Article XI) – Uphold ethical behavior in personal and public life. 9. Render Civic Service – Participate in community service and volunteer activities. Civil Society Organizations, Social Movements and Non-movements • Political participation outside formal institutions Community Engagement and Development • Definition and Forms of Community Engagement: o Volunteerism o Community organizing o Participatory governance o Advocacy and civic movements o Public consultations and forums • Principles of Effective Community Engagement: o Inclusivity and participation o Empowerment of local communities o Collaboration and partnership building • Role of Community Engagement in Development: o Enhancing public services o Promoting sustainable development o Strengthening civic participation Community Action'),
  ('Citizenship and Civic Engagement', 12, 'G12-006', 'Recognize the importance of solidarity in promoting national and global community development (e.g., poverty alleviation)', NULL, NULL, '6. Respect the Rights of Others (Article III) – Uphold the dignity and freedoms of fellow citizens. 7. Protect the Environment (Article II, Section 16) Contribute to Environmental Preservation. 8. Practice Honesty and Integrity (Article XI) – Uphold ethical behavior in personal and public life. 9. Render Civic Service – Participate in community service and volunteer activities. Civil Society Organizations, Social Movements and Non-movements • Political participation outside formal institutions Community Engagement and Development • Definition and Forms of Community Engagement: o Volunteerism o Community organizing o Participatory governance o Advocacy and civic movements o Public consultations and forums • Principles of Effective Community Engagement: o Inclusivity and participation o Empowerment of local communities o Collaboration and partnership building • Role of Community Engagement in Development: o Enhancing public services o Promoting sustainable development o Strengthening civic participation Community Action'),
  ('Citizenship and Civic Engagement', 12, 'G12-007', 'Conduct a PESTLE analysis to identify major issues affecting one’s community', NULL, NULL, '• What is PESTLE analysis? • Major issues affecting one’s own community Types of Community Action Initiatives: • Grassroots Movements: Locally-driven campaigns for social change • Non-Governmental Organization (NGO) Initiatives: Advocacy for specific issues (e.g., human rights, environmental protection) • Youth-Led Initiatives: Student councils, youth groups, and volunteer organizations • Barangay-Based Programs: Local government projects addressing community needs Sample community action initiatives • Environmental Advocacy: Clean-up drives, reforestation projects • Health Campaigns: Community vaccination programs, health awareness drives • Livelihood Programs: Skills training and micro-enterprise projects • Disaster Response: Community resilience projects during natural calamities'),
  ('Citizenship and Civic Engagement', 12, 'G12-008', 'Evaluate selected cases of community action initiatives', NULL, NULL, '• What is PESTLE analysis? • Major issues affecting one’s own community Types of Community Action Initiatives: • Grassroots Movements: Locally-driven campaigns for social change • Non-Governmental Organization (NGO) Initiatives: Advocacy for specific issues (e.g., human rights, environmental protection) • Youth-Led Initiatives: Student councils, youth groups, and volunteer organizations • Barangay-Based Programs: Local government projects addressing community needs Sample community action initiatives • Environmental Advocacy: Clean-up drives, reforestation projects • Health Campaigns: Community vaccination programs, health awareness drives • Livelihood Programs: Skills training and micro-enterprise projects • Disaster Response: Community resilience projects during natural calamities'),
  ('Citizenship and Civic Engagement', 12, 'G12-009', 'Analyze different methodologies and approaches to community action and partnerships with local groups', NULL, NULL, 'Participatory Methodologies and Approaches of Community Actions and Involvements Partnership building with local groups Community Profiling and Mapping Needs Assessment Participatory Action Planning'),
  ('Citizenship and Civic Engagement', 12, 'G12-010', 'Conduct community profiling and mapping and needs assessment using the appropriate tools', NULL, NULL, 'Participatory Methodologies and Approaches of Community Actions and Involvements Partnership building with local groups Community Profiling and Mapping Needs Assessment Participatory Action Planning'),
  ('Citizenship and Civic Engagement', 12, 'G12-011', 'Develop partnerships with local groups for community development and resource mobilization and a community action plan using participatory approaches and evaluation tools for a community action initiative', NULL, NULL, 'Resource Mobilization Community Action Plan Evaluation (Rubrics) Community Action Initiative: Field Practicum'),
  ('Citizenship and Civic Engagement', 12, 'G12-012', 'Implement community action initiatives', NULL, NULL, 'Resource Mobilization Community Action Plan Evaluation (Rubrics) Community Action Initiative: Field Practicum'),
  ('Citizenship and Civic Engagement', 12, 'G12-013', 'Evaluate the implementation of the community action initiatives', NULL, NULL, 'Resource Mobilization Community Action Plan Evaluation (Rubrics) Community Action Initiative: Field Practicum'),
  ('Citizenship and Civic Engagement', 12, 'G12-014', 'Reflect on the insights and learnings gained from the community action initiative', NULL, NULL, 'Resource Mobilization Community Action Plan Evaluation (Rubrics) Community Action Initiative: Field Practicum'),
  ('Contemporary Literature 1', 12, 'G12-001', 'Describe the role of literature in reflecting and challenging personal and collective identity.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 1', 12, 'G12-002', 'Explore Philippine literature (including regional works) as a way of understanding personal and local heritage and identity.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 1', 12, 'G12-003', 'Demonstrate understanding and appreciation of how composers use forms and features purposefully to engage responders at a personal level.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 1', 12, 'G12-004', 'Use a variety of approaches to engage at a personal level with written, spoken and multimodal texts, including poetry.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-005', 'Identify how themes in literary texts connect to personal identity and experiences (e.g., family, belonging, wellbeing).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-006', 'Respond to literary texts in ways that promote personal connection (e.g., reading log, journaling, thematic maps, reviews, personal essays).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-007', 'Explain how composers use literary forms and features to foster personal connection of the responder in affective and intellectual ways.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-008', 'Participate in interactive learning (e.g., group discussions and read-alouds) to deepen empathy and understanding of literary texts.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-009', 'Consider how literary works shape or challenge personal beliefs, values, or emotions.', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 1', 12, 'G12-010', 'Review one’s interaction with literary texts, identifying strengths and areas for growth to cultivate empathy and personal awareness.', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 1', 12, 'G12-011', 'LITERATURE AS WINDOW: TEXTUAL PERSPECTIVES', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 1', 12, 'G12-012', 'The learner understands literature as a product of cultural and social contexts, and how it continues to shape and reflect contemporary realities and conversations.', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 1', 12, 'G12-013', 'Discuss literature’s role in shaping cultural understanding and dialogue.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 1', 12, 'G12-014', 'Explore contemporary global literature (including literary works by Filipinos of broad reach) as a way of understanding the world.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 1', 12, 'G12-015', 'Demonstrate understanding and appreciation of how composers use forms and features purposefully to shape and challenge cultural and social assumptions, understandings, and perspectives.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 1', 12, 'G12-016', 'Use a variety of approaches to make meaning of the world through written, spoken and multimodal texts, including short stories or a novella.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-017', 'Identify recurring themes in Philippine and global literary texts (e.g., cultural identity, justice seeking, migration, protest and resistance).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-018', 'Respond to literary texts in ways that promote social connection (e.g., discussion, book club, team-based games such as ‘hot seat’, group presentations, collaborative essays).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-019', 'Explain how composers use literary forms and features to resonate with contemporary audiences, making connections to current social concerns and real-world events.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-020', 'Participate in interactive learning (e.g., debates and forums) to deepen understanding and appreciation of other perspectives of literary texts.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 1', 12, 'G12-021', 'Consider how literary texts shape or challenge one’s understanding of other people and their social and cultural contexts.', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 1', 12, 'G12-022', 'Review one’s interaction with literary texts, identifying strengths and areas for growth to cultivate cultural awareness and outward thinking.', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 2', 12, 'G12-001', 'Discuss the concept of literature as a conversation across texts, contexts, and time periods.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-002', 'Explore adaptations of canonical or historical literary texts into contemporary forms, including film or TV series.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-003', 'Identify how global and local media adaptations reflect evolving values or social norms.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-004', 'Demonstrate understanding of how composers use forms and features (e.g., film/TV language) to transform, repurpose and recontextualize original texts for new audiences.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-005', 'Compare and contrast original literary texts with their adapted versions (e.g., Shakespearean play and film, novella and TV series)', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 2', 12, 'G12-006', 'Identify how techniques of transformation (e.g., intertextual references, narrative shifts, motifs or symbols, updated setting, or character changes) establish connections between the original work and the adaptation.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 2', 12, 'G12-007', 'Respond creatively and critically to adaptations (e.g., rewriting scenes, storyboard pitches, comparative written or video essays).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 2', 12, 'G12-008', 'Explain how adaptations can open new interpretive possibilities, challenge dominant readings, and raise ethical considerations (e.g., plagiarism or borrowing).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 2', 12, 'G12-009', 'Participate in collaborative analysis and interactive activities (e.g., panel discussions, genre re-imaginings) around interpretations of adapted works.', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 2', 12, 'G12-010', 'Reflect on how the comparative study of original texts and their adapted versions enhances understanding and appreciation of both texts.', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 2', 12, 'G12-011', 'Review one’s interaction with literary texts, identifying strengths and areas for growth to cultivate awareness of intertextuality and changing norms and values.', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 2', 12, 'G12-012', 'LITERATURE AS BEACON: TEXTUAL INNOVATIONS', NULL, NULL, 'Reflecting on the impact and value of literature along one’s personal literary journey'),
  ('Contemporary Literature 2', 12, 'G12-013', 'Discuss the emerging purposes and value of digital literature (e.g., hypertext fiction, interactive storytelling, social media poetry).', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-014', 'Explore the works of contemporary literary innovators pushing genre or form boundaries, especially from the Philippines and Asia-Pacific.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-015', 'Identify how technological and social changes influence the evolution of literary forms.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-016', 'Demonstrate understanding and appreciation of how creators purposefully use textual innovations (e.g., multimodality, hybridity, user interactivity) in digital texts to engage and reach contemporary audiences.', NULL, NULL, 'Demonstrating knowledge and appreciation of literature and its purposes'),
  ('Contemporary Literature 2', 12, 'G12-017', 'Engage with digital and experimental literary texts using interactive platforms (e.g., webcomics, augmented narratives, text-based games).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 2', 12, 'G12-018', 'Identify key themes in innovative literature (e.g., AI, surveillance, virtual identity, gender, climate futures).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
