  ('Contemporary Literature 2', 12, 'G12-020', 'Respond creatively and critically to digital and experimental texts (e.g., school-based lit fest, creative essay forms, adapting the adaptation).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
  ('Contemporary Literature 2', 12, 'G12-021', 'Participate in multimodal critiques (e.g., podcast reviews, screen recordings with commentary, digital annotation), considering alternative perspectives of literature (e.g., digital humanities, ecocriticism, queer theory).', NULL, NULL, 'Engaging flexibly with literary texts to produce personal and critical responses'),
