  ('Creative Composition 1', 12, 'G12-012', 'SHAPE AND SOUND – POETIC SELF-EXPRESSION', NULL, NULL, 'Inquiry'),
  ('Creative Composition 1', 12, 'G12-013', 'The learner demonstrates deep understanding of poetic elements, structures, and devices; explores how form, imagery, sound, and language to make meaning, convey emotion, and express self in poetry. - Inquiry', NULL, NULL, 'Inquiry'),
  ('Creative Composition 1', 12, 'G12-014', 'Distinguish key features of poetry based on ideas, structure, language, and purpose.', NULL, NULL, 'Inquiry'),
